#![verifier::loop_isolation(false)]
#![allow(non_snake_case)]

use verus_state_machines_macros::tokenized_state_machine;
use vstd::atomic::*;
use vstd::cell::CellId;
use vstd::cell::pcell as pc;
use vstd::invariant::*;
use vstd::prelude::*;
use vstd::tokens::*;
use core::marker::PhantomData;
